import unittest

from solution import aggregate_sales


class AcceptanceTests(unittest.TestCase):
    def test_quoted_fields_and_negative_sales(self):
        data = 'city,amount\r\n" Paris, TX ", 4\r\n\r\n"Paris, TX",-2\r\nparis,3\r\n'
        self.assertEqual(aggregate_sales(data), {'Paris, TX': 2, 'paris': 3})
        self.assertEqual(aggregate_sales('city,amount\n'), {})

    def test_invalid_rows(self):
        for row in ('A,nope', 'A,1.5', ' ,2', 'B'):
            with self.subTest(row=row), self.assertRaises(ValueError):
                aggregate_sales('city,amount\n' + row + '\n')
